package dev.industrialtechnology.expansion;
import cpw.mods.fml.common.network.simpleimpl.*;import cpw.mods.fml.common.network.ByteBufUtils;import io.netty.buffer.ByteBuf;import net.minecraft.nbt.NBTTagCompound;import dev.industrialtechnology.core.IndustrialTechnology;
public final class ExpansionSnapshot implements IMessage {public int window;public NBTTagCompound state;public ExpansionSnapshot(){}public ExpansionSnapshot(int w,NBTTagCompound n){window=w;state=n;}public void toBytes(ByteBuf b){b.writeInt(window);ByteBufUtils.writeTag(b,state);}public void fromBytes(ByteBuf b){window=b.readInt();state=ByteBufUtils.readTag(b);}public static final class Handler implements IMessageHandler<ExpansionSnapshot,IMessage>{public IMessage onMessage(ExpansionSnapshot m,MessageContext c){IndustrialTechnology.proxy.acceptExpansion(m.window,m.state);return null;}}}
